import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    cid = {}
    parent = []
    risk = []
    first = {}
    seen = {'d': {}, 'k': {}}

    def find(x):
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != r:
            parent[x], x = r, parent[x]
        return r

    for i in range(n):
        c, d, k, r = data[1 + i].split(':')
        if c not in cid:
            cid[c] = len(parent)
            parent.append(len(parent))
            risk.append(int(r))
        u = cid[c]
        for tab, key in ((seen['d'], d), (seen['k'], k)):
            if key in tab:
                a, b = find(u), find(tab[key])
                if a != b:
                    parent[a] = b
            else:
                tab[key] = u
    m = len(parent)
    order = {}
    size = []
    tot = []
    cnt = []
    for i in range(m):
        r = find(i)
        if r not in order:
            order[r] = len(size)
            size.append(0)
            tot.append(0)
            cnt.append(0)
        j = order[r]
        size[j] += 1
        if risk[i] > 0:
            tot[j] += risk[i]
            cnt[j] += 1
    scores = [tot[j] // cnt[j] for j in range(len(size)) if cnt[j] > 0]
    print(len(size))
    print(max(size))
    print(' '.join(map(str, scores)) if scores else 'NONE')

